package com.cenedu.backend.domain.problem.authoring.diagram; import static org.assertj.core.api.Assertions.*; import java.util.*; import org.junit.jupiter.api.Test;
class DiagramTableValidationTest { @Test void rejectsDuplicateAndOutOfRangeCells(){var s=new DiagramStyle("#000000","#FFFFFF","#FF0000",1,"sans-serif",12);var v=new DiagramViewport(640,240,16);var d=new DataTableDiagramSpecV1(1,"T",DiagramKind.DATA_TABLE,v,s,List.of("r"),List.of("c"),List.of(new TableCellSpec(1,0,null,"x")),Set.of());assertThatThrownBy(()->new DiagramSpecValidator().validate(d,Map.of())).isInstanceOf(DiagramValidationException.class);} }
